<?php
require_once __DIR__ . '/../../includes/db.php';require_once __DIR__ . '/../includes/auth.php';require_login();
$from=$_GET['from']??'';$to=$_GET['to']??'';
$whereParts = ['c.status=\'IN_STOCK\'', 'c.purchase_date <= DATE_SUB(CURDATE(), INTERVAL 30 DAY)'];$params=[];$types='';
if($from!==''&&$to!==''){$whereParts[]='c.purchase_date BETWEEN ? AND ?';$types.='ss';$params[]=$from;$params[]=$to;}
$where = count($whereParts) ? 'WHERE '.implode(' AND ',$whereParts) : '';
$sql="SELECT c.id,c.car_name,c.plate_number,c.chassis_number,c.purchase_price,c.purchase_date,c.status,IFNULL(cc.total_cost,0) total_cost,cs.sale_price,cs.sale_date,cs.buyer_name,(IFNULL(cs.sale_price,0)-(c.purchase_price+IFNULL(cc.total_cost,0))) profit FROM cars c LEFT JOIN (SELECT car_id,SUM(amount) total_cost FROM car_costs GROUP BY car_id) cc ON c.id=cc.car_id LEFT JOIN car_sales cs ON c.id=cs.car_id $where ORDER BY c.created_at DESC";
$stmt=$conn->prepare($sql);if($types){$stmt->bind_param($types,...$params);} $stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
if(($_GET['format']??'')==='pdf'){require_once __DIR__.'/report_pdf.php';$pdfRows=[];foreach($rows as $r){$pdfRows[]=[ $r['car_name'],car_sales_plate_label($r['plate_number']),money($r['purchase_price']),money($r['total_cost']),$r['sale_price']!==null?money($r['sale_price']):'--',$r['status'],$r['status']==='SOLD'?money($r['profit']):'--',$r['purchase_date'] ];}output_report_pdf('Old Stock Report',['Car','Plate','Purchase','Costs','Sale','Status','Profit','Purchase Date'],$pdfRows,[48,32,28,26,28,24,28,34],'old_stock_report.pdf');}
$page_title='Old Stock Report';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';
?>
<div class="content-page"><div class="report-title"><h1 class="page-title">Old Stock Report</h1><div><a class="btn btn-red" href="?format=pdf&from=<?=urlencode($from)?>&to=<?=urlencode($to)?>">Download PDF</a><a class="btn btn-dark" href="index.php">Back</a></div></div><div class="card"><form class="filter-bar" method="get"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Filter</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Car</th><th>Plate</th><th>Purchase</th><th>Costs</th><th>Sale</th><th>Status</th><th>Profit</th><th>Purchase Date</th></tr></thead><tbody><?php if($rows): foreach($rows as $r):?><tr><td><?=e($r['car_name'])?></td><td><?=e(car_sales_plate_label($r['plate_number']))?></td><td><?=money($r['purchase_price'])?></td><td><?=money($r['total_cost'])?></td><td><?= $r['sale_price']!==null?money($r['sale_price']):'—' ?></td><td><span class="badge <?=$r['status']==='SOLD'?'sold':'stock'?>"><?=e($r['status'])?></span></td><td><?= $r['status']==='SOLD'?money($r['profit']):'—' ?></td><td><?=e($r['purchase_date'])?></td></tr><?php endforeach; else:?><tr><td colspan="8">No records found.</td></tr><?php endif;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
